{
  "category_edits": [
    {
      "category": "hyperparameter_tuning",
      "rationale": "Jointly increase learning rate to 8e-4 and reduce dropout to 0.05 across all four category models. Faster updates with less stochastic suppression may improve fitting of short histories. Preserve width 48, six causal blocks, batch size 128, Adam, existing model formulas, and one checkpoint per category. Predictor shapes remain compatible.",
      "edits": [
        {
          "find": "DROPOUT_RATE  = float(os.environ.get(\"NEXTITNET_DROPOUT\", \"0.10\"))",
          "replace": "DROPOUT_RATE  = float(os.environ.get(\"NEXTITNET_DROPOUT\", \"0.05\"))"
        },
        {
          "find": "LR            = float(os.environ.get(\"NEXTITNET_LR\", \"6e-4\"))",
          "replace": "LR            = float(os.environ.get(\"NEXTITNET_LR\", \"8e-4\"))"
        }
      ]
    }
  ],
  "change_summary": "Jointly raise learning rate and lower dropout for all four independent NextItNet models, preserving routing, architecture, loss, seeds, and training limits."
}
